"""Low level interaction functions for the Plan Approval window and related dialogs for the Monaco Application."""

import os
from .objects.monaco_core_objects import MonacoCoreObjects
from . import dashboard as MonacoDashboard
from . import common_monaco_ops as CommonMonacoOps
from interops.libraries.squish_actions import CommonActions
from interops.libraries.squish_actions.exceptions import FailedToFindObject
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import MONACO_APP_NAME


#<-------------------------------> Plan Approval and related Functions <------------------------------->

@deco.set_separate_app_context(MONACO_APP_NAME)
def check_for_plan_approval_dialog(waitTimeout: int = 5, acknowledgePatientShiftDialogWithEnterKey: bool = False) -> bool:
    """Waits for the Plan Approval dialog to appear > acknowledges the Export upon approval dialog if it appears.

    :param waitTimeout: Integer value of the time in seconds to wait for the Plan Approval dialog to appear.
    """
    if CommonActions.wait_for_object_to_appear(MonacoCoreObjects.plan_Approval_Dialog, waitTimeout):
        MonacoDashboard.acknowledge_export_of_patient_shift_enabled_dialog(okWithEnterKey=acknowledgePatientShiftDialogWithEnterKey)
        return True
    return False


@deco.set_separate_app_context(MONACO_APP_NAME)
def save_plan_as(plan_name: str) -> None:
    """Locates the Save Plan As dialog > Populates the given plan name field > Clicks the Save button
    """
    try:
        if CommonActions.find_object(MonacoCoreObjects.save_Plan_Dialog) is not None:
            CommonActions.left_click_object_no_move(MonacoCoreObjects.save_Plan_Name_Combobox_Field)
            CommonActions.press_key_sequence_ctrl_a()
            CommonActions.press_delete_key()
            CommonActions.type_in_textfield(MonacoCoreObjects.save_Plan_Name_Combobox_Field, plan_name)
            # Click Save button
            CommonActions.left_click_object(MonacoCoreObjects.save_Plan_Save_Button)
            # Check Plan Approval Dialog appears
            CommonActions.wait_for_object_to_appear(MonacoCoreObjects.plan_Approval_Dialog)

    except FailedToFindObject:
        print("Save Plan As dialog did not appear")


@deco.set_separate_app_context(MONACO_APP_NAME)
def toggle_export_uppon_approval_checkbox(enableCheckbox: bool = True) -> None:
    """Locates the Plan Approval dialog > checks to see if the Export upon approval check box is enabled > if not enabled, the check box is set to enabled.

    param enableCheckbox: Boolean value to determine if the Export Upon Approval checkbox should be checked or unchecked.
    """
    if CommonActions.find_object(MonacoCoreObjects.plan_Approval_Dialog) is not None:
        export_upon_approval_checkbox = CommonActions.find_object(MonacoCoreObjects.plan_Approval_Dialog_Export_Upon_Approval_Button)
        try:
            # Check if the checkbox is already checked using image verification as the 'enabled' property of the checkbox/button object type
            # always reports True even when the the checbox is unchecked, so this property is not reliable for this check.
            dest_checkbox_checked_image_path = os.path.abspath(os.path.join(CommonMonacoOps.get_monaco_image_folder_path(),
                                                                            "dicom_export_checkbox_checked.png"))

            image_search_options = {"timeout": 3000, "threshold": 95.0}
            checkbox_checked = CommonActions.wait_for_image_object(dest_checkbox_checked_image_path, image_search_options, export_upon_approval_checkbox)
        except Exception as e:
            checkbox_checked = None

        if enableCheckbox:
            if checkbox_checked is None:
                CommonActions.left_click_object(export_upon_approval_checkbox)
        else:
            if checkbox_checked is not None:
                CommonActions.left_click_object(export_upon_approval_checkbox)


@deco.set_separate_app_context(MONACO_APP_NAME)
def is_approved_checkbox_checked() -> bool:
    """Locates the Plan Approval dialog > checks to see if the Approved check box is checked/ enabled > return the status as a bool

    param enableCheckbox: Boolean value to determine if the Export Upon Approval checkbox should be checked or unchecked.
    """
    if CommonActions.find_object(MonacoCoreObjects.plan_Approval_Dialog) is not None:
        if len(CommonActions.find_object(MonacoCoreObjects.plan_Approval_Reviewer_Textbox).text) != 0: # type: ignore
            # Approved checkbox is checked (Plan is already approved)
            return True
    return False


@deco.set_separate_app_context(MONACO_APP_NAME)
def check_approved_checkbox(isSsoEnabled: bool = False, close_dialog_if_approved: bool = True) -> None:
    """Locates the Plan Approval dialog > checks to see if the plan is already in an approved state > if in an unapproved state, the Approved check box is set to enabled and
    it waits for the User Validation dialog to appear.

    :param bool isSsoEnabled: Boolean value to determine if the SSO is enabled or not. If SSO is enabled, the User Validation dialog will not appear.
    :param close_dialog_if_approved: Boolean value to determine if the Plan Approval dialog should be closed if the plan is already in an approved state.
    """
    if is_approved_checkbox_checked():
        print('Plan is already in an approved state. Exiting function...')
        if close_dialog_if_approved:
            click_done_button_in_plan_approval_dialog()
    else:
        CommonActions.left_click_object(MonacoCoreObjects.plan_Approval_Dialog_Approved_Button)
        if not isSsoEnabled:
            CommonActions.wait_for_object_to_appear(MonacoCoreObjects.user_Validation_Dialog)


@deco.set_separate_app_context(MONACO_APP_NAME)
def uncheck_approved_checkbox(isSsoEnabled: bool = False, close_dialog_if_unapproved: bool = True) -> None:
    """Locates the Plan Approval dialog > checks to see if the plan is already in an unapproved state > if in an approved state, the Approved check box is set to disabled and
    it waits for the User Validation dialog to appear.

    :param bool isSsoEnabled: Boolean value to determine if the SSO is enabled or not. If SSO is enabled, the User Validation dialog will not appear.
    :param close_dialog_if_unapproved: Boolean value to determine if the Plan Approval dialog should be closed if the plan is already in an unapproved state.
    """
    if not is_approved_checkbox_checked():
        print('Plan is already in an unapproved state. Exiting function...')
        if close_dialog_if_unapproved:
            click_done_button_in_plan_approval_dialog()
    else:
        CommonActions.left_click_object(MonacoCoreObjects.plan_Approval_Dialog_Approved_Button)
        if not isSsoEnabled:
            CommonActions.wait_for_object_to_appear(MonacoCoreObjects.user_Validation_Dialog)


@deco.set_separate_app_context(MONACO_APP_NAME)
def sign_off_plan_approval(username: str, password: str) -> None:
    """Locates the User Validation dialog and enters the given username and password variables into the respective text boxes > The OK button is then clicked and
    we wait for the User Validation dialog to disappear.

    :param username: String value of the username to be entered into the User Validation dialogs username text box.
    :type username: str
    :param password: String value of the password to be entered into the User Validation dialogs password text box.
    :type password: str
    """
    if CommonActions.find_object(MonacoCoreObjects.user_Validation_Dialog) is not None:
        MonacoDashboard.enter_username(username)
        MonacoDashboard.enter_password(password)
        MonacoDashboard.click_login_ok_button()
        CommonActions.wait_for_object_to_disappear(MonacoCoreObjects.user_Validation_Dialog)


@deco.set_separate_app_context(MONACO_APP_NAME)
def click_done_button_in_plan_approval_dialog() -> None:
    """Locates the Plan Approval dialog and clicks the Done button before waiting for the Plan Approval dialog disappears.
    """
    if CommonActions.find_object(MonacoCoreObjects.plan_Approval_Dialog) is not None:
        CommonActions.left_click_object(MonacoCoreObjects.plan_Approval_Dialog_Done_Button)
        CommonActions.wait_for_object_to_disappear(MonacoCoreObjects.plan_Approval_Dialog)

